const item = $input.first().json;
const b = (item && item.body) ? item.body : (item || {});
const payment = (b && b.payment && typeof b.payment === "object") ? b.payment : {};
const customer = (b && b.customer && typeof b.customer === "object") ? b.customer : {};

const ALLOWED_EVENT_TYPES = ["payment_failed"];
const ALLOWED_METHODS = ["card", "upi", "netbanking", "wallet", "bank_transfer"];

const errors = [];

function present(v) {
  return v !== undefined && v !== null && v !== "";
}
function isNum(v) {
  return v !== null && v !== undefined && v !== "" && !isNaN(Number(v));
}
function num(v) {
  return isNum(v) ? Number(v) : v;
}

// Derive payment_id from top level or nested payment
const paymentId = present(b.payment_id) ? b.payment_id
  : (present(payment.payment_id) ? payment.payment_id : null);

// Top-level required fields
const topRequired = ["event_id", "event_type", "timestamp", "source", "recovery_attempt_count"];
for (const f of topRequired) {
  if (!present(b[f]) && b[f] !== 0) errors.push("Missing field: " + f);
}
if (!paymentId) errors.push("Missing field: payment_id");
if (!b.payment || typeof b.payment !== "object") errors.push("Missing field: payment");
if (!b.customer || typeof b.customer !== "object") errors.push("Missing field: customer");

// Payment required fields
const paymentRequired = ["amount", "currency", "status", "payment_method", "failed_at", "time_since_failure_hours"];
for (const f of paymentRequired) {
  if (!present(payment[f]) && payment[f] !== 0) errors.push("Missing payment field: " + f);
}

// Customer required fields
const customerRequired = ["customer_id", "notification_count", "customer_age_days", "previous_successful_payments", "previous_failed_payments", "previous_recovery_attempts", "customer_lifetime_value", "average_previous_payment", "recent_payment_frequency"];
for (const f of customerRequired) {
  if (!present(customer[f]) && customer[f] !== 0) errors.push("Missing customer field: " + f);
}

// Allowed-value checks
const eventType = String(b.event_type || "").toLowerCase();
if (present(b.event_type) && !ALLOWED_EVENT_TYPES.includes(eventType)) {
  errors.push("Invalid event_type: " + b.event_type);
}
const method = String(payment.payment_method || "").toLowerCase();
if (present(payment.payment_method) && !ALLOWED_METHODS.includes(method)) {
  errors.push("Invalid payment_method: " + payment.payment_method);
}

// Currency: max 3 chars, normalized to uppercase
const currency = String(payment.currency || "").toUpperCase();
if (present(payment.currency) && (currency.length < 1 || currency.length > 3)) {
  errors.push("Invalid currency: " + payment.currency);
}

// ISO datetime checks
function isIso(v) {
  if (!present(v)) return false;
  const d = new Date(v);
  return !isNaN(d.getTime());
}
if (present(b.timestamp) && !isIso(b.timestamp)) errors.push("Invalid timestamp (not ISO datetime): " + b.timestamp);
if (present(payment.failed_at) && !isIso(payment.failed_at)) errors.push("Invalid payment.failed_at (not ISO datetime): " + payment.failed_at);

// Numeric type checks
const numericTop = ["recovery_attempt_count"];
for (const f of numericTop) {
  if (present(b[f]) && !isNum(b[f])) errors.push("Invalid numeric value: " + f);
}
const numericPayment = ["amount", "time_since_failure_hours"];
for (const f of numericPayment) {
  if (present(payment[f]) && !isNum(payment[f])) errors.push("Invalid numeric value: payment." + f);
}
const numericCustomer = ["notification_count", "customer_age_days", "previous_successful_payments", "previous_failed_payments", "previous_recovery_attempts", "customer_lifetime_value", "average_previous_payment", "recent_payment_frequency"];
for (const f of numericCustomer) {
  if (present(customer[f]) && !isNum(customer[f])) errors.push("Invalid numeric value: customer." + f);
}

// Build clean API payload (payment_id at TOP LEVEL, numbers as numbers, lowercased enums)
const api_payload = {
  event_id: b.event_id,
  event_type: eventType,
  timestamp: b.timestamp,
  source: b.source,
  recovery_attempt_count: num(b.recovery_attempt_count),
  payment_id: paymentId,
  payment: {
    payment_id: paymentId,
    amount: num(payment.amount),
    currency: currency,
    status: payment.status,
    payment_method: method,
    failed_at: payment.failed_at,
    time_since_failure_hours: num(payment.time_since_failure_hours)
  },
  customer: {
    customer_id: customer.customer_id,
    notification_count: num(customer.notification_count),
    customer_age_days: num(customer.customer_age_days),
    previous_successful_payments: num(customer.previous_successful_payments),
    previous_failed_payments: num(customer.previous_failed_payments),
    previous_recovery_attempts: num(customer.previous_recovery_attempts),
    customer_lifetime_value: num(customer.customer_lifetime_value),
    average_previous_payment: num(customer.average_previous_payment),
    recent_payment_frequency: num(customer.recent_payment_frequency)
  }
};

return [{
  json: {
    valid: errors.length === 0,
    error_message: errors.length ? errors.join("; ") : null,
    event_id: present(b.event_id) ? b.event_id : null,
    payment_id: paymentId,
    api_payload
  }
}];

const items = $input.all();

function errorOut(message, paymentId, eventId, evaluation) {
  return [{
    json: {
      ok: false,
      action: "ERROR",
      status: "error",
      payment_id: paymentId != null ? paymentId : null,
      event_id: eventId != null ? eventId : null,
      message,
      evaluation: evaluation != null ? evaluation : null
    }
  }];
}

if (!items.length) {
  return errorOut("Reclaim returned no response.", null, null, null);
}

let data = items[0].json;

// Handle n8n HTTP error item (onError: continueRegularOutput)
if (data && data.error) {
  const err = data.error;
  const httpCode = err.httpCode || (err.context && err.context.httpCode) || null;
  const msg = err.message || err.description || String(err);
  const prefix = String(httpCode) === "422" ? "Reclaim API validation failed: " : "Reclaim API request failed: ";
  return errorOut(prefix + msg, null, null, { error: err });
}

// Handle string body
if (typeof data === "string") {
  try { data = JSON.parse(data); } catch (e) {
    return errorOut("Reclaim returned invalid JSON.", null, null, null);
  }
}

if (!data || typeof data !== "object") {
  return errorOut("Reclaim returned an empty response.", null, null, null);
}

// Unwrap a body wrapper if present
if (data.body && typeof data.body === "object" && !data.action && !data.decision) {
  data = data.body;
}

const paymentId = data.payment_id != null ? data.payment_id
  : (data.payment && data.payment.payment_id != null ? data.payment.payment_id
  : (data.decision && data.decision.payment_id != null ? data.decision.payment_id : null));

const eventId = data.event_id != null ? data.event_id
  : (data.decision && data.decision.event_id != null ? data.decision.event_id : null);

let apiAction = data.action != null ? data.action
  : (data.decision && data.decision.action != null ? data.decision.action : null);
if (typeof apiAction === "string") apiAction = apiAction.trim().toUpperCase();

const eligible = data.eligible != null ? data.eligible
  : (data.recovery_eligible != null ? data.recovery_eligible
  : (data.decision && data.decision.recovery_eligible != null ? data.decision.recovery_eligible : null));

const requiresApproval = data.requires_approval != null ? data.requires_approval
  : (data.decision && data.decision.requires_approval != null ? data.decision.requires_approval : false);

const duplicate = data.duplicate != null ? data.duplicate : false;

const validationStatus = data.validation_status != null ? data.validation_status
  : (data.decision && data.decision.validation_status != null ? data.decision.validation_status : null);

const allowed = ["RETRY", "PAYMENT_LINK", "REMINDER", "ESCALATE", "STOP"];

// Missing / unsupported action -> ERROR
if (!apiAction) {
  return errorOut("Recovery action missing from Reclaim response.", paymentId, eventId, data);
}
if (!allowed.includes(apiAction)) {
  return errorOut("Unsupported recovery action: " + apiAction, paymentId, eventId, data);
}

// Deterministic safety overrides (precedence order)
let action = apiAction;
let message;
if (duplicate === true) {
  action = "STOP";
  message = "Duplicate event detected; recovery stopped.";
} else if (eligible === false) {
  action = "STOP";
  message = "Recovery is not eligible; recovery stopped.";
} else if (apiAction === "STOP") {
  action = "STOP";
  message = "Evaluation returned STOP; recovery stopped.";
} else if (requiresApproval === true) {
  action = "ESCALATE";
  message = "Recovery requires manual approval; escalated for review.";
} else {
  action = apiAction;
  message = "Validated recovery action: " + action + ".";
}

return [{
  json: {
    ok: true,
    action,
    status: "success",
    payment_id: paymentId,
    event_id: eventId,
    risk_score: data.risk_score != null ? data.risk_score : (data.decision && data.decision.risk_score != null ? data.decision.risk_score : null),
    eligible: eligible,
    requires_approval: requiresApproval,
    priority: data.priority != null ? data.priority : (data.decision && data.decision.priority != null ? data.decision.priority : null),
    confidence: data.confidence != null ? data.confidence : (data.decision && data.decision.confidence != null ? data.decision.confidence : null),
    validation_status: validationStatus,
    duplicate: duplicate,
    message,
    evaluation: data
  }
}];
